/*
You are given an array of `n` integers where each element is either a positive integer or 0. Write a C++ function `int minimalNonZeroSegments(const std::vector<int>& arr)` that returns the minimum possible number of non-zero segments after you are allowed to perform the following operation exactly once (or zero times, if you prefer): choose any contiguous subarray and set all its elements to 0. More precisely, you may pick a segment `[l, r]` (1-indexed, with `1 ≤ l ≤ r ≤ n`) and replace every element in that range with 0. After this operation (or without doing it), the array is divided into maximal contiguous blocks of non-zero values; each such block is a "non-zero segment". The goal is to minimize the number of such segments. Note that if the entire array becomes zeros, the number of non-zero segments is 0. The function must handle cases where the array already has zeros, including leading, trailing, or multiple adjacent zeros, and it must return the minimum possible count. Constraints: `1 ≤ n ≤ 10^6`, each `arr[i]` is between 0 and 10^9. The answer will always be between 0 and 2, and you must return that integer.
*/

#include <vector>
#include <algorithm>

// Returns the minimum of the number of maximal non-zero segments and 2.
// A non-zero segment is a maximal contiguous block of elements that are not zero.
int minimalNonZeroSegments(const std::vector<int>& arr) {
    int segments = 0;
    bool inSegment = false;
    
    for (int value : arr) {
        if (value != 0) {
            if (!inSegment) {
                ++segments;
                inSegment = true;
            }
        } else {
            inSegment = false;
        }
    }
    
    return std::min(segments, 2);
}

#include <cassert>
#include <vector>
#include "solution.h" // assume the above is in a header

int main() {
    // All zeros -> 0 segments
    assert(minimalNonZeroSegments({0, 0, 0}) == 0);
    // Single non-zero -> 1 segment
    assert(minimalNonZeroSegments({5}) == 1);
    // Single zero -> 0 segments
    assert(minimalNonZeroSegments({0}) == 0);
    // Two separate non-zero segments -> 2 (but capped at 2)
    assert(minimalNonZeroSegments({1, 0, 2}) == 2);
    // Three separate non-zero segments -> cap at 2
    assert(minimalNonZeroSegments({1, 0, 2, 0, 3}) == 2);
    // Adjacent non-zeros form one segment
    assert(minimalNonZeroSegments({4, 5, 6}) == 1);
    // Mixed with leading/trailing zeros
    assert(minimalNonZeroSegments({0, 7, 8, 0, 9, 0}) == 2);
    // All non-zero -> 1 segment
    assert(minimalNonZeroSegments({1, 2, 3, 4}) == 1);
    // One segment after zeros
    assert(minimalNonZeroSegments({0, 0, 3, 4, 0}) == 1);
    // Many segments cap at 2
    assert(minimalNonZeroSegments({1,0,2,0,3,0,4,0,5}) == 2);
    return 0;
}

